         <div>Submit the quiz to check your answers.</div>
       </div>
     </form>
   </main>

   <script>
     const form = document.getElementById('quiz-form');
     const result = document.getElementById('result');

     const answerKey = {
       q1: ['Python', 'JavaScript'],
       q2: ['Go', 'Rust', 'C#'],
       q3: ['HTML', 'CSS', 'SQL']
     };

     function getSelectedValues(name) {
       return Array.from(form.elements[name] || [])
         .filter((input) => input.checked)
         .map((input) => input.value)
         .sort();
     }

     function sameSelection(selected, expected) {
       if (selected.length !== expected.length) {
         return false;
       }

       return selected.every((value, index) => value === expected[index]);
     }

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const total = Object.keys(answerKey).length;
       const correct = Object.entries(answerKey).reduce((score, [name, expected]) => {
         const selected = getSelectedValues(name);
         return score + (sameSelection(selected, [...expected].sort()) ? 1 : 0);
       }, 0);

       result.dataset.state = 'done';
       result.innerHTML = `<strong>Your score</strong><div>You matched ${correct} of ${total} questions.</div>`;
     });
   </script>
